// THE PLAYER'S CHOICES ------------------------------------------------------------------

export type AbilityMethod = 'standard' | 'pointBuy' | 'roll';

export interface CreationChoices {
  name: string;
  /** Species, class and background by SRD id. */
  species: string;
  size?: CreationSpecies['sizeOptions'][number];
  class: string;
  background: string;
  abilities: {
    method: AbilityMethod;
    /** Scores before the background's increases. */
    base: AbilityScores;
    /** For 'roll': the server's ability roll these scores came from. */
    rollId?: string;
  };
  backgroundBonus: BackgroundChoice;
  /** The class's skill choices (the background's two skills come on their own). */
  skills: SkillKey[];
  equipment: { class: string; background: string };
  spells: { cantrips: string[]; prepared: string[]; spellbook: string[] };
  alignment: string;
  details: CharacterDetails;
}

export const STANDARD_ARRAY: readonly number[] = [15, 14, 13, 12, 10, 8];
/** Ability Score Point Costs (SRD): scores 8 to 15. */
export const POINT_COSTS: Readonly<Record<number, number>> = { 8: 0, 9: 1, 10: 2, 11: 3, 12: 4, 13: 5, 14: 7, 15: 9 };
export const POINT_BUY_BUDGET = 27;
/** The Wizard's spellbook "starts with six level 1 Wizard spells of your choice" (SRD Wizard, Spellbook). */
export const WIZARD_STARTING_SPELLBOOK = 6;
export const ALIGNMENTS = [
  'Lawful good',
  'Neutral good',
  'Chaotic good',
  'Lawful neutral',
  'Neutral',
  'Chaotic neutral',
  'Lawful evil',
  'Neutral evil',
  'Chaotic evil',
] as const;
export const DETAIL_FIELDS = ['personalityTraits', 'ideals', 'bonds', 'flaws', 'appearance', 'backstory'] as const;
const DETAIL_MAX = 4000;

/** The wizard's steps, in order. Every problem names the step it belongs to. */
export const CREATION_STEPS = [
  'origin',
  'class',
  'background',
  'abilities',
  'skills',
  'equipment',
  'spells',
  'details',
] as const;
export type CreationStep = (typeof CREATION_STEPS)[number];

export interface CreationProblem {
  step: CreationStep;
  message: string;
}

// READING A PAYLOAD (shape only) -------------------------------------------------------

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
const isStr = (v: unknown, max: number): v is string => typeof v === 'string' && v.length <= max;
const strList = (v: unknown, max = 40): v is string[] =>
  Array.isArray(v) && v.length <= max && v.every(s => isStr(s, 80));

/**
 * Checks that a payload has the shape of CreationChoices (types and lengths only; the rules come after), so a
 * hand-made request cannot crash the checks. Returns the choices, or what is wrong with the shape.
 */
export function readCreationChoices(v: unknown): { choices: CreationChoices } | { error: string } {
  if (!isObj(v)) return { error: 'The choices must be an object' };
  const { name, size, abilities, backgroundBonus, skills, equipment, spells, alignment, details } = v;
  if (!isStr(name, 200)) return { error: 'name must be text' };
  for (const key of ['species', 'class', 'background'] as const) {
    if (!isStr(v[key], 80)) return { error: `${key} must be an SRD id` };
  }
  if (size !== undefined && !['tiny', 'small', 'medium', 'large'].includes(size as string))
    return { error: 'size must be tiny, small, medium or large' };
  if (!isObj(abilities) || !['standard', 'pointBuy', 'roll'].includes(abilities.method as string))
    return { error: 'abilities.method must be standard, pointBuy or roll' };
  const base = abilities.base;
  if (!isObj(base) || !ABILITY_KEYS.every(a => Number.isInteger(base[a])))
    return { error: 'abilities.base needs a whole number for each ability' };
  if (abilities.rollId !== undefined && !isStr(abilities.rollId, 80)) return { error: 'abilities.rollId must be text' };
  if (
    !isObj(backgroundBonus) ||
    !(
      backgroundBonus.plusOneEach === true ||
      (ABILITY_KEYS.includes(backgroundBonus.plus2 as Ability) &&
        ABILITY_KEYS.includes(backgroundBonus.plus1 as Ability))
    )
  )
    return { error: 'backgroundBonus must be { plus2, plus1 } or { plusOneEach: true }' };
  if (!strList(skills, 18)) return { error: 'skills must be a list of skills' };
  if (!isObj(equipment) || !isStr(equipment.class, 2) || !isStr(equipment.background, 2))
    return { error: 'equipment needs a class option and a background option' };
  if (!isObj(spells) || !strList(spells.cantrips) || !strList(spells.prepared) || !strList(spells.spellbook))
    return { error: 'spells needs cantrips, prepared and spellbook lists' };
  if (!isStr(alignment, 40)) return { error: 'alignment must be text' };
  if (!isObj(details) || !DETAIL_FIELDS.every(k => isStr(details[k], DETAIL_MAX)))
    return { error: `details needs ${DETAIL_FIELDS.join(', ')} as text of up to ${DETAIL_MAX} characters` };
  return {
    choices: {
      name,
      species: v.species as string,
      ...(size !== undefined ? { size: size as CreationChoices['size'] } : {}),
      class: v.class as string,
      background: v.background as string,
      abilities: {
        method: abilities.method as AbilityMethod,
        base: Object.fromEntries(ABILITY_KEYS.map(a => [a, base[a]])) as AbilityScores,
        ...(abilities.rollId !== undefined ? { rollId: abilities.rollId as string } : {}),
      },
      backgroundBonus:
        backgroundBonus.plusOneEach === true
          ? { plusOneEach: true }
          : { plus2: backgroundBonus.plus2 as Ability, plus1: backgroundBonus.plus1 as Ability },
      skills: skills as SkillKey[],
      equipment: { class: equipment.class as string, background: equipment.background as string },
      spells: {
        cantrips: spells.cantrips as string[],
        prepared: spells.prepared as string[],
        spellbook: spells.spellbook as string[],
      },
      alignment,
      details: Object.fromEntries(DETAIL_FIELDS.map(k => [k, details[k]])) as unknown as CharacterDetails,
    },
  };
}

// THE RULES -----------------------------------------------------------------------------

/** Points a set of base scores costs under point buy, or null when a score is outside 8 to 15. */
export function pointBuyCost(scores: AbilityScores): number | null {
  let total = 0;
  for (const a of ABILITY_KEYS) {
    const cost = POINT_COSTS[scores[a]];
    if (cost === undefined) return null;
    total += cost;
  }
  return total;
}

/** "4d6, drop the lowest": one total per set of four dice. */
export function abilityRollTotals(dice: readonly number[]): number[] {
  if (dice.length !== 24 || !dice.every(d => Number.isInteger(d) && d >= 1 && d <= 6)) {
    throw new RangeError('An ability roll is six sets of four d6');
  }
  return Array.from({ length: 6 }, (_, i) => {
    const set = dice.slice(i * 4, i * 4 + 4);
    return set.reduce((s, d) => s + d, 0) - Math.min(...set);
  });
}

const sameMultiset = (a: readonly number[], b: readonly number[]) =>
  a.length === b.length && [...a].sort((x, y) => x - y).join() === [...b].sort((x, y) => x - y).join();

/** Weapon training from a class's Weapon Proficiencies text, e.g. "Simple and Martial weapons". */
export function weaponTrainingOf(text: string): WeaponTraining[] {
  const t = text.toLowerCase();
  const out: WeaponTraining[] = [];
  if (/\bsimple\b/.test(t)) out.push('simple');
  if (t.includes('martial weapons that have')) {
    if (/\blight\b/.test(t)) out.push('martial-light');
    if (/\bfinesse\b/.test(t)) out.push('martial-finesse');
  } else if (t.includes('martial weapons')) out.push('martial');
  return out;
}

const level1 = (c: CreationClass) => c.levels.find(l => l.level === 1)?.columns ?? {};
const count = (v: number | string | undefined) => (typeof v === 'number' ? v : 0);

/** How many cantrips, prepared spells and spellbook spells a class chooses at level 1. */
export function spellAllowance(c: CreationClass): { cantrips: number; prepared: number; spellbook: number } {
  if (!c.spellcasting) return { cantrips: 0, prepared: 0, spellbook: 0 };
  const cols = level1(c);
  return {
    cantrips: count(cols.cantrips),
    prepared: count(cols.preparedSpells),
    spellbook: c.spellcasting.preparation === 'spellbook' ? WIZARD_STARTING_SPELLBOOK : 0,
  };
}

/** What the SRD records the choices name, or undefined where a choice names nothing. */
export function lookUp(choices: Pick<CreationChoices, 'species' | 'class' | 'background'>, srd: CreationSrd) {
  return {
    species: srd.species.find(s => s.id === choices.species),
    cls: srd.classes.find(c => c.id === choices.class),
    background: srd.backgrounds.find(b => b.id === choices.background),
  };
}

/** The scores after the background's increases, or the reason they cannot be worked out. */
export function finalScores(
  choices: Pick<CreationChoices, 'abilities' | 'backgroundBonus'>,
  background: CreationBackground,
): { scores: AbilityScores } | { problem: string } {
  try {
    return { scores: applyBackground(choices.abilities.base, background, choices.backgroundBonus) };
  } catch (e) {
    return { problem: (e as Error).message };
  }
}

/**
 * Every rule a set of choices breaks, by step. Pass `rolledTotals` (the six totals of the player's ability roll,
 * as the server recorded it) when the method is 'roll'. An empty list means the character can be created.
 * `steps` limits the checks to some steps (the wizard checks each step as the player reaches it).
 */
export function creationProblems(
  choices: CreationChoices,
  srd: CreationSrd,
  rolledTotals?: readonly number[],
  steps: readonly CreationStep[] = CREATION_STEPS,
): CreationProblem[] {
  const problems: CreationProblem[] = [];
  const want = (step: CreationStep) => steps.includes(step);
  const add = (step: CreationStep, message: string) => problems.push({ step, message });
  const { species, cls, background } = lookUp(choices, srd);

  if (want('origin')) {
    const name = choices.name.trim();
    if (name.length < 1 || name.length > 80) add('origin', 'Give your character a name of up to 80 letters.');
    if (!species) add('origin', 'Choose a species.');
    else if (species.sizeOptions.length > 1 && !(choices.size && species.sizeOptions.includes(choices.size)))
      add('origin', `Choose your size: ${species.sizeOptions.join(' or ')}.`);
    else if (choices.size && !species.sizeOptions.includes(choices.size))
      add('origin', `A ${species.name} is ${species.sizeOptions.join(' or ')}.`);
  }
  if (want('class') && !cls) add('class', 'Choose a class.');
  if (want('background') && !background) add('background', 'Choose a background.');

  if (want('abilities')) {
    const base = choices.abilities.base;
    const values = ABILITY_KEYS.map(a => base[a]);
    if (choices.abilities.method === 'standard' && !sameMultiset(values, STANDARD_ARRAY)) {
      add('abilities', `Use each of the standard array's scores once: ${STANDARD_ARRAY.join(', ')}.`);
    }
    if (choices.abilities.method === 'pointBuy') {
      const cost = pointBuyCost(base);
      if (cost === null) add('abilities', 'With point buy, every score is from 8 to 15.');
      else if (cost > POINT_BUY_BUDGET) add('abilities', `That costs ${cost} points; you have ${POINT_BUY_BUDGET}.`);
    }
    if (choices.abilities.method === 'roll') {
      if (!rolledTotals) add('abilities', 'Roll your ability scores first.');
      else if (!sameMultiset(values, rolledTotals))
        add('abilities', `Use each of your rolled scores once: ${rolledTotals.join(', ')}.`);
    }
    if (background) {
      const r = finalScores(choices, background);
      if ('problem' in r) add('abilities', r.problem);
    }
  }

  if (want('skills') && cls) {
    const picked = choices.skills;
    if (new Set(picked).size !== picked.length) add('skills', 'Choose each skill only once.');
    for (const s of picked) {
      if (!SKILL_KEYS.includes(s)) add('skills', `${s} is not a skill.`);
      else if (!cls.skillChoices.from.includes(s)) add('skills', `${cls.name}s cannot choose ${s}.`);
      else if (background?.skillProficiencies.includes(s))
        add('skills', `Your background already gives ${s}; choose another.`);
    }
    if (picked.length !== cls.skillChoices.count)
      add('skills', `Choose ${cls.skillChoices.count} skills from the ${cls.name} list.`);
  }

  if (want('equipment')) {
    if (cls && !cls.startingEquipmentOptions.some(o => o.option === choices.equipment.class))
      add('equipment', `Choose one of the ${cls.name}'s equipment options.`);
    if (background && !background.equipmentOptions.some(o => o.option === choices.equipment.background))
      add('equipment', `Choose one of the ${background.name} background's equipment options.`);
  }

  if (want('spells') && cls) {
    const allow = spellAllowance(cls);
    const { cantrips, prepared, spellbook } = choices.spells;
    const onList = (name: string, level: number) =>
      srd.spells.some(s => s.name === name && s.level === level && s.classes.includes(cls.name));
    const checkList = (list: string[], level: number, size: number, what: string) => {
      if (new Set(list).size !== list.length) add('spells', `Choose each ${what} only once.`);
      for (const n of list) {
        if (!onList(n, level)) add('spells', `${n} is not a level ${level} ${cls.name} spell.`);
      }
      if (list.length !== size)
        add('spells', size ? `Choose ${size} ${what}${size === 1 ? '' : 's'}.` : `${cls.name}s choose no ${what}s.`);
    };
    checkList(cantrips, 0, allow.cantrips, 'cantrip');
    if (allow.spellbook) {
      checkList(spellbook, 1, allow.spellbook, 'spellbook spell');
      if (prepared.some(p => !spellbook.includes(p))) add('spells', 'Prepare spells from your spellbook.');
    } else if (spellbook.length) add('spells', `${cls.name}s have no spellbook.`);
    checkList(prepared, 1, allow.prepared, 'prepared spell');
  }

  if (want('details')) {
    if (choices.alignment && !(ALIGNMENTS as readonly string[]).includes(choices.alignment))
      add('details', `Alignment is one of: ${ALIGNMENTS.join(', ')}.`);
  }
  return problems;
}

// EQUIPMENT --------------------------------------------------------------------------------

export interface StartingItem {
  name: string;
  quantity: number;
  kind: ItemKind;
  definition: ItemDefinition;
  weight: number | null;
  valueCp: number;
  srdRef: string | null;
  equipped: boolean;
}

const COIN_CP: Record<string, number> = { cp: 1, sp: 10, ep: 50, gp: 100, pp: 1000 };
const singular = (s: string) => [s, s.replace(/es$/, ''), s.replace(/s$/, '')];

/**
 * Reads an equipment option as the SRD prints it ("Chain Mail, Greatsword, Flail, 8 Javelins, Dungeoneer's Pack,
 * and 4 GP") into items and gold. Weapons and armour named in the SRD tables become those records; anything else
 * becomes gear named as printed.
 */
export function readEquipmentOption(
  text: string,
  srd: Pick<CreationSrd, 'weapons' | 'armor'>,
): { items: Omit<StartingItem, 'equipped'>[]; gp: number } {
  let gp = 0;
  const items: Omit<StartingItem, 'equipped'>[] = [];
  for (const raw of text.split(/,\s*/)) {
    const part = raw.replace(/^and\s+/i, '').trim();
    if (!part) continue;
    const coins = /^(\d+)\s*GP$/i.exec(part);
    if (coins) {
      gp += Number(coins[1]);
      continue;
    }
    const counted = /^(\d+)\s+(.+)$/.exec(part);
    const quantity = counted ? Number(counted[1]) : 1;
    const name = counted ? counted[2] : part;
    const match = <T extends { name: string }>(list: T[]) =>
      list.find(x => singular(name.toLowerCase()).includes(x.name.toLowerCase()));
    const weapon = match(srd.weapons);
    const armor = weapon ? undefined : match(srd.armor);
    if (weapon) {
      items.push({
        name: weapon.name,
        quantity,
        kind: 'weapon',
        definition: {
          weapon: {
            category: weapon.category,
            kind: weapon.kind,
            damage: weapon.damage,
            properties: weapon.properties,
            ...(weapon.versatileDice ? { versatileDice: weapon.versatileDice } : {}),
            ...(weapon.range ? { range: weapon.range } : {}),
            ...(weapon.ammunition ? { ammunition: weapon.ammunition } : {}),
            mastery: weapon.mastery,
          },
        },
        weight: weapon.weightLb,
        valueCp: Math.round(weapon.cost.amount * (COIN_CP[weapon.cost.coin] ?? 100)),
        srdRef: weapon.id,
      });
    } else if (armor) {
      items.push({
        name: armor.name,
        quantity,
        kind: armor.category === 'shield' ? 'shield' : 'armor',
        definition: {
          armor: {
            category: armor.category,
            baseAc: armor.baseAc,
            strength: armor.strength,
            stealthDisadvantage: armor.stealthDisadvantage,
          },
        },
        weight: armor.weightLb,
        valueCp: Math.round(armor.cost.amount * (COIN_CP[armor.cost.coin] ?? 100)),
        srdRef: armor.id,
      });
    } else {
      items.push({ name, quantity, kind: 'gear', definition: {}, weight: null, valueCp: 0, srdRef: null });
    }
  }
  return { items, gp };
}

// BUILDING THE CHARACTER ---------------------------------------------------------------------

export interface BuiltCharacter {
  /** The stored sheet (name and xp also have their own columns). */
  sheet: CharacterSheet;
  items: StartingItem[];
  gp: number;
}

/**
 * The level 1 character the choices make. Call it only when creationProblems finds none (it throws otherwise).
 * Hit points are the Hit Point Die's maximum plus the Constitution modifier; armour, a shield and the weapons the
 * character is trained with start equipped.
 */
export function buildCharacter(choices: CreationChoices, srd: CreationSrd): BuiltCharacter {
  const { species, cls, background } = lookUp(choices, srd);
  if (!species || !cls || !background) throw new RangeError('Choose a species, a class and a background first');
  const final = finalScores(choices, background);
  if ('problem' in final) throw new RangeError(final.problem);
  const scores = final.scores;
  const training = weaponTrainingOf(cls.weaponProficiencies);
  const classKit = cls.startingEquipmentOptions.find(o => o.option === choices.equipment.class);
  const backgroundKit = background.equipmentOptions.find(o => o.option === choices.equipment.background);
  const kits = [classKit, backgroundKit].map(k => (k ? readEquipmentOption(k.text, srd) : { items: [], gp: 0 }));

  let wearing = false;
  let holdingShield = false;
  const items: StartingItem[] = kits
    .flatMap(k => k.items)
    .map(i => {
      let equipped = false;
      if (i.definition.armor?.category === 'shield' && !holdingShield) equipped = holdingShield = true;
      else if (i.definition.armor && i.definition.armor.category !== 'shield' && !wearing) equipped = wearing = true;
      else if (i.definition.weapon && trainedWith(i.definition.weapon, training)) equipped = true;
      return { ...i, equipped };
    });

  const hp = hitPointsAtLevel1(cls.hitDie, abilityModifier(scores.con));
  const allow = spellAllowance(cls);
  const sheet: CharacterSheet = {
    name: choices.name.trim(),
    species: species.name,
    className: cls.name,
    background: background.name,
    alignment: choices.alignment,
    xp: 0,
    levelApplied: 1,
    weaponProficiencies: training,
    abilityScores: scores,
    skillProficiencies: [...new Set([...background.skillProficiencies, ...choices.skills])],
    expertise: [],
    saveProficiencies: [...cls.saveProficiencies],
    hp: { max: hp, current: hp, temp: 0 },
    hitDice: { die: cls.hitDie, total: 1, spent: 0 },
    speed: species.speed,
    armor: null,
    shield: false,
    weapons: [],
    equipment: [],
    inspiration: false,
    size: choices.size ?? species.sizeOptions[0],
    originFeat: background.originFeat.name,
    toolProficiency: background.toolProficiency,
    ...(cls.spellcasting
      ? {
          spells: {
            cantrips: [...choices.spells.cantrips],
            prepared: [...choices.spells.prepared],
            ...(allow.spellbook ? { spellbook: [...choices.spells.spellbook] } : {}),
          },
        }
      : {}),
    details: { ...choices.details },
  };
  return { sheet, items, gp: kits.reduce((s, k) => s + k.gp, 0) };
}

/** The built character's items as the rules engine's InventoryItem, for computeSheet's preview. */
export function previewItems(built: BuiltCharacter): InventoryItem[] {
  return built.items.map((i, n) => ({
    id: `new-${n}`,
    name: i.name,
    kind: i.kind,
    definition: i.definition,
    weight: i.weight,
    quantity: i.quantity,
    requiresAttunement: false,
    equipped: i.equipped,
    attuned: false,
  }));
}
